import { useContext } from 'react';

import { useStoreSelector } from '../../../../core/store/selector.js';
import { HistogramChartStateContext } from '../../contexts/HistogramChartState.context.js';
import { HistogramChartState } from '../../types/state.js';

export const useSelector = <T>(
  selector: (state: HistogramChartState) => T,
): T => useStoreSelector(HistogramChartStateContext, selector);

export const useFilteredSeriesIdsState = () =>
  useSelector((state: HistogramChartState) => state.filteredSeriesIds);

export const useHighlightedSeriesIdsState = () =>
  useSelector((state: HistogramChartState) => state.highlightedSeriesIds);

export const useOverlaysState = () =>
  useSelector((state: HistogramChartState) => state.overlays);

export const usePinnedTooltipState = () =>
  useSelector((state: HistogramChartState) => state.overlays.pinnedTooltip);

export const useVisibleTooltipState = () =>
  useSelector((state: HistogramChartState) => state.overlays.visibleTooltip);

export const useAnnotationsHighlightedMarkers = () =>
  useSelector(
    (state: HistogramChartState) => state.annotations.highlightedMarkersIds,
  );

export const useAnnotationsHoveredMarkers = () =>
  useSelector(
    (state: HistogramChartState) => state.annotations.hoveredMarkersIds,
  );
export const useCurrentDomainState = () =>
  useSelector((state: HistogramChartState) => state.currentDomain);

export const useZoomState = () =>
  useSelector((state: HistogramChartState) => state.zoom);

export const useSetState = () => {
  const { setState } = useContext(HistogramChartStateContext);

  return setState;
};

export const useHoveredThresholdIdState = () =>
  useSelector((state: HistogramChartState) => state.hoveredThresholdId);
